t","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Termite treatment products","unit":"lump sum","costType":"material","treatment":"marked_up"}]},{"name":"Rodents & Exclusion","items":[{"name":"Rodent bait stations, exterior","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Interior trapping","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Exclusion sealing (entry points)","unit":"linear foot","costType":"labor","treatment":"marked_up"},{"name":"Door sweep install","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Exclusion materials","unit":"lump sum","costType":"material","treatment":"marked_up"},{"name":"Dead animal removal","unit":"each","costType":"labor","treatment":"marked_up"}]},{"name":"Specialty Services","items":[{"name":"Bed bug treatment","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Stinging insect nest removal","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Wildlife trapping and removal","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Fumigation","unit":"lump sum","costType":"subcontractor","treatment":"marked_up"}]},{"name":"Setup & Travel","items":[{"name":"Trip charge","unit":"each","costType":"other","treatment":"marked_up"},{"name":"Minimum service charge","unit":"lump sum","costType":"other","treatment":"marked_up"},{"name":"State or local filing fee","unit":"each","costType":"permit","treatment":"pass_through"}]},{"name":"Labor","items":[{"name":"Pest control technician labor","unit":"hour","costType":"labor","treatment":"marked_up"}]}],"examples":[{"name":"Pest inspection","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Initial interior and exterior treatment","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Quarterly service visit","unit":"each","costType":"labor","treatment":"marked_up"},{"name":"Exterior perimeter treatment","unit":"linear foot","costType":"labor","treatmen