insert into public.academy_trades (slug, name, family, icon, intro, seo_title, seo_description, sales_challenge, sort_order) values
  ('pest-control', 'Pest Control', 'General', 'Bug', 'Pest control companies grow on recurring service plans, clear explanations of what each visit covers, and licensed technicians who work safely. This classroom covers licensing and insurance, quoting initial treatments and service plans, termite and rodent work, routing, technician training and building a book of recurring customers.', 'Pest Control Business Courses', 'Pest control business courses on licensing, quoting service plans, termite and rodent work, route scheduling, technician training and recurring revenue.', 'Customers often compare a one-time spray price with a full service plan and can''t tell why the numbers differ. Separate the initial treatment from the recurring visit, name the pests covered and say what callbacks are included so they compare the same thing.', 280)
insert into public.academy_courses (id, slug, trade_slug, pillar, title, summary, description, level, access, status, content_class, cover_theme, featured, sort_order, planned_lessons, seo_title, seo_description, published_at) values
  (md5('academy:course:pest-control-getting-started')::uuid, 'pest-control-getting-started', 'pest-control', 'getting_started', 'Starting a Pest Control Business: Licensing, Insurance and Equipment', 'Business basics for a pest control company, from applicator licensing to the first service vehicle.', 'Commercial pesticide application requires a license in every state, so licensing and insurance come first. This course covers entity setup, state applicator certification and business licensing, general liability and pollution coverage, and choosing a first vehicle, sprayers and storage. Requirements vary by state; confirm them with your state pesticide regulatory agency and insurance agent.', 'beginner', 'public', 'upcoming', 'original', 'slate', false, 10, array['Entity setup and tax registration basics', 'State applicator certification and business licensing', 'Liability and pollution insurance', 'Choosing a vehicle, equipment and safe storage', 'Setting a service area and minimum job']::text[], null, 'Business basics for a pest control company, from applicator licensing to the first service vehicle.', null),
  (md5('academy:course:pest-control-sales')::uuid, 'pest-control-sales', 'pest-control', 'sales', 'Selling Pest Control: Initial Treatments and Service Plans', 'Help customers understand what the first service and each plan visit cover.', 'Customers often compare a one-time spray with a full plan. This course covers inspecting with the customer, explaining the initial treatment and the recurring visit separately, naming the pests covered, explaining callbacks, and following up on termite and rodent quotes.', 'intermediate', 'public', 'upcoming', 'original', 'cyan', false, 20, array['Inspecting with the customer', 'Separating the initial treatment from the plan', 'Naming covered pests and callbacks', 'Showing licensing and insurance', 'Following up on termite and rodent quotes']::text[], 'Selling Pest Control: Initial Treatments and Service Plans', 'Help customers understand what the first service and each plan visit cover.', null),
  (md5('academy:course:pest-control-estimating')::uuid, 'pest-control-estimating', 'pest-control', 'estimating', 'Pest Control Estimates: Visits, Perimeter and Specialty Work', 'Price initial services, plan visits and specialty work from your own production times.', 'Home size, perimeter, activity level and visit frequency drive most pest pricing. This course covers estimating technician time from your own records, pricing initial and recurring visits, linear-foot termite and exclusion work, bait stations, and specialty services like bed bugs and wildlife.', 'intermediate', 'public', 'upcoming', 'original', 'navy', false, 30, array['Sizing the home: area and perimeter', 'Initial and recurring visit pricing', 'Termite trenching and bait stations', 'Rodent exclusion by the linear foot', 'Specialty services and minimums']::text[], 'Pest Control Estimates: Visits, Perimeter and Specialty Work', 'Price initial services, plan visits and specialty work from your own production times.', null),
  (md5('academy:course:pest-control-project-management')::uuid, 'pest-control-project-management', 'pest-control', 'project_management', 'Routing, Scheduling and Service Records', 'Plan efficient routes and keep clear records for every visit.', 'Recurring pest work lives or dies on routing and records. This course covers building dense routes, scheduling monthly, bi-monthly and quarterly visits, customer notices and prep instructions, weather reschedules, and keeping the service and application records your state requires.', 'intermediate', 'public', 'upcoming', 'original', 'green', false, 40, array['Building dense routes', 'Scheduling recurring visits', 'Customer notices and prep instructions', 'Weather and reschedules', 'Service and application records']::text[], 'Routing, Scheduling and Service Records', 'Plan efficient routes and keep clear records for every visit.', null),
  (md5('academy:course:pest-control-accounting')::uuid, 'pest-control-accounting', 'pest-control', 'accounting', 'Pest Control Financials: Recurring Revenue and Route Profit', 'Know what each route, plan and technician really earns.', 'Recurring revenue makes pest control predictable when the numbers are clear. This course covers costing visits and routes, tracking product and vehicle costs, billing service plans, measuring customer churn, and setting aside taxes and overhead.', 'intermediate', 'public', 'upcoming', 'original', 'amber', false, 50, array['Costing visits and routes', 'Product and vehicle costs', 'Billing service plans', 'Measuring churn and retention', 'Setting aside taxes and overhead']::text[], 'Pest Control Financials: Recurring Revenue and Route Profit', 'Know what each route, plan and technician really earns.', null),
  (md5('academy:course:pest-control-hr')::uuid, 'pest-control-hr', 'pest-control', 'hr', 'Hiring and Training Pest Control Technicians', 'Recruit, license and keep technicians who work safely and talk well with customers.', 'Technicians are the face of a pest company. This course covers recruiting, supervised training toward state certification, continuing education credits, pay and route incentives, and keeping good technicians. Licensing and employment rules vary by state; follow the laws where you operate.', 'beginner', 'public', 'upcoming', 'original', 'rose', false, 60, array['Recruiting technicians', 'Training toward state certification', 'Continuing education credits', 'Pay and route incentives', 'Keeping good technicians']::text[], 'Hiring and Training Pest Control Technicians', 'Recruit, license and keep technicians who work safely and talk well with customers.', null),
  (md5('academy:course:pest-control-growth')::uuid, 'pest-control-growth', 'pest-control', 'growth', 'Growing a Pest Control Company: Plans, Commercial Accounts and Referrals', 'Build a book of recurring customers and steady commercial work.', 'Growth in pest control comes from recurring plans. This course covers converting one-time jobs into plans, adding mosquito and termite services, serving property managers, restaurants and other commercial accounts, real estate inspection work, and asking for reviews and referrals.', 'intermediate', 'public', 'upcoming', 'original', 'cyan', false, 70, array['Turning one-time jobs into plans', 'Adding seasonal and termite services', 'Commercial and property manager accounts', 'Real estate inspection work', 'Reviews and referrals']::text[], null, 'Build a book of recurring customers and steady commercial work.', null),
  (md5('academy:course:pest-control-safety')::uuid, 'pest-control-safety', 'pest-control', 'safety', 'Pesticide Safety, Label Compliance and PPE', 'Keep technicians, customers and pets safe on every visit.', 'Safe pest control starts with the label. This course covers reading and following product labels, protective equipment, safe mixing, transport and storage, spill response, and customer prep and re-entry instructions. The label is the law: follow it, EPA and OSHA rules, and the regulations where you work.', 'beginner', 'public', 'upcoming', 'original', 'slate', false, 80, array['Reading and following the label', 'Protective equipment', 'Mixing, transport and storage', 'Spill response', 'Customer prep and re-entry']::text[], 'Pesticide Safety, Label Compliance and PPE', 'Keep technicians, customers and pets safe on every visit.', null)
