-- Built2Bid: adds Pest Control as a trade (the app already has it in code).
-- 1) trade list + estimate template, 2) Contractor Academy classroom with 8 "Coming soon" course cards.
-- Safe to re-run: upserts for the trade list order, ON CONFLICT DO NOTHING for everything else.
-- Paste into the Supabase SQL Editor and Run: https://supabase.com/dashboard/project/asiiqmegvajtuspeumio/sql/new
begin;

-- Trade list. Re-applies the whole list so the sort order matches the app (Pest Control sits after Cleaning).
on conflict (slug) do update set name = excluded.name, icon = excluded.icon, family = excluded.family, featured = excluded.featured, sort_order = excluded.sort_order;

on conflict (trade_slug, version) do nothing;

-- Academy classroom.
on conflict (slug) do nothing;

-- Keep the Academy classroom order in step with the trade list (only the sort order changes).
update public.academy_trades t set sort_order = v.sort_order
from (values ('roofing', 0), ('siding', 10), ('decks', 20), ('concrete', 30), ('kitchens', 40), ('bathrooms', 50), ('interior-remodeling', 60), ('exterior-remodeling', 70), ('drywall', 80), ('painting', 90), ('electrical', 100), ('plumbing', 110), ('hvac', 120), ('flooring', 130), ('tile', 140), ('framing', 150), ('finish-carpentry', 160), ('cabinets-countertops', 170), ('windows-doors', 180), ('insulation', 190), ('gutters', 200), ('fencing', 210), ('landscaping', 220), ('tree-removal', 230), ('tree-trimming', 240), ('pressure-washing', 250), ('soft-washing', 260), ('cleaning', 270), ('pest-control', 280), ('excavation', 290), ('foundations', 300), ('masonry', 310), ('asphalt-paving', 320), ('demolition', 330), ('basements', 340), ('additions', 350), ('garages', 360), ('pole-barns', 370), ('commercial-remodeling', 380), ('general-contracting', 390), ('handyman', 400)) as v(slug, sort_order)
where t.slug = v.slug and t.sort_order is distinct from v.sort_order;

on conflict do nothing;

on conflict do nothing;

commit;
